'use strict';
const $=s=>document.querySelector(s),copy=v=>JSON.parse(JSON.stringify(v)),safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const definitions=[
{id:'intent',name:'의도 분류',type:'LLM',icon:'◈',fields:['model','prompt'],description:'질문을 분류하고 검색 방향을 정합니다.'},
{id:'retrieve',name:'지식 검색',type:'RAG',icon:'⌕',fields:['knowledge'],description:'선택한 지식에서 답변 근거를 찾습니다.'},
{id:'tool',name:'도구 호출',type:'TOOL',icon:'↗',fields:['tools'],description:'주문과 문의의 현재 상태를 확인합니다.'},
{id:'answer',name:'답변 생성',type:'LLM',icon:'◇',fields:['model','prompt','knowledge','tools'],description:'근거와 도구 결과로 최종 답변을 생성합니다.'}
];
const base={intent:{model:'balanced',prompt:'intent v3',body:'고객 질문을 주문·배송·반품으로 분류하세요.',knowledge:'고객 서비스 가이드',tools:[]},retrieve:{model:'balanced',prompt:'retrieve v1',body:'관련 정책을 검색하세요.',knowledge:'고객 서비스 가이드',topK:'5',tools:[]},tool:{model:'balanced',prompt:'tool v1',body:'주문 상태를 조회하세요.',knowledge:'고객 서비스 가이드',tools:['order-status']},answer:{model:'balanced',prompt:'support v12',body:'고객 서비스 근거에 따라 조건을 명확하게 설명하세요. 확인되지 않은 내용은 추측하지 마세요.',knowledge:'고객 서비스 가이드',tools:['ticket-search']}};
const samples=[{id:'D01',input:'반품 배송비는 얼마인가요?',expected:'단순 변심은 3,000원, 불량·오배송은 무료입니다.'},{id:'D02',input:'출고 후 배송지를 변경할 수 있나요?',expected:'출고 후에는 고객센터에 문의해야 합니다.'},{id:'D03',input:'환불은 언제 완료되나요?',expected:'영업일 기준 3~5일이 필요합니다.'}];
const old=copy(base);old.answer.prompt='support v11';old.answer.body='질문에 간결하게 답변하세요.';
function preset(){return [{id:'EXP-041',mode:'eval',time:'오늘 10:16',input:'고객 지원 회귀 v4',config:copy(old),state:'완료',statuses:{intent:'완료',retrieve:'완료',tool:'완료',answer:'완료'},output:'',results:samples.map((q,i)=>({...q,score:[.85,.71,null][i],output:q.expected,error:i===2?'Judge 일시 오류':null})),judge:'답변 품질 v2',dataset:'고객 지원 회귀 v4',changed:['answer']},{id:'RUN-032',mode:'run',time:'오늘 10:12',input:samples[0].input,config:copy(old),state:'완료',statuses:{intent:'완료',retrieve:'완료',tool:'완료',answer:'완료'},output:'단순 변심은 3,000원이며 상품 불량은 무료입니다.',results:[],changed:['answer']}];}
let state={mode:'run',selected:'answer',draft:copy(base),input:samples[0].input,history:preset(),historyOpen:false,filter:'current',viewId:null,baseline:'EXP-041',resultId:null,item:0,tab:'response',dataset:'고객 지원 회귀 v4',judge:'답변 품질 v2',error:''};
try{let cached=JSON.parse(localStorage.getItem('kpap-node-mock-v1'));if(cached)state={...state,...cached,viewId:null,error:''}}catch{}
let running=null,runToken=0,noticeTimer,beforeHistory=null;state.history.filter(r=>r.state==='진행 중').forEach(r=>{r.state='중단';Object.keys(r.statuses).forEach(k=>{if(r.statuses[k]==='진행')r.statuses[k]='중단'})});
function save(){try{localStorage.setItem('kpap-node-mock-v1',JSON.stringify(state))}catch{}}
function badge(t,c=''){return '<span class="badge '+c+'">'+safe(t)+'</span>'}
function button(t,a,c='',extras=''){return '<button class="btn '+c+'" data-action="'+a+'" '+extras+'>'+t+'</button>'}
function opt(v,t,selected){return '<option value="'+safe(v)+'" '+(v===selected?'selected':'')+'>'+safe(t)+'</option>'}
function field(t,id,control,h=''){return '<div class="field"><label for="'+id+'">'+t+'</label>'+control+(h?'<p class="hint">'+h+'</p>':'')+'</div>'}
function select(id,items,value,disabled=false){return '<select id="'+id+'" data-field="'+id+'" '+(disabled?'disabled':'')+'>'+items.map(v=>opt(v,v,value)).join('')+'</select>'}
function viewed(){return state.history.find(r=>r.id===state.viewId)||null}
function result(){return viewed()||state.history.find(r=>r.id===state.resultId)||null}
function dirty(id){return JSON.stringify(state.draft[id])!==JSON.stringify(base[id])}
function branch(input){return /(주문|배송지|출고|환불)/.test(input)?'tool':'retrieve'}
function graphStatuses(r){if(!r)return {};if(r.state!=='완료')return r.statuses;const input=r.mode==='eval'?r.results[state.item]?.input:r.input,route=branch(input||'');return {...r.statuses,[route==='tool'?'retrieve':'tool']:'생략'}}
function graph(){const r=result(),statuses=graphStatuses(r),cfg=(state.mode==='trace'?r?.config:null)||viewed()?.config||state.draft,route=r?(r.mode==='eval'?branch(r.results[state.item]?.input||''):r.route||branch(r.input)):null;
const edge=(id,cls)=>'class="edge '+(route===id?cls:'')+'"';
return '<section class="panel flow-panel" aria-label="노드 그래프"><div class="canvas"><div class="graph-stage"><svg class="edges" viewBox="0 0 600 680" aria-label="입력에서 의도 분류 후 정책 또는 주문 경로로 분기하고 답변에서 합류"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="context-stroke"/></marker></defs><path class="edge '+(r?'used':'')+'" d="M300 72 V126"/><path '+edge('retrieve','used')+' d="M300 220 V254 Q300 270 284 270 H162 Q145 270 145 286 V322"/><path '+edge('tool','used')+' d="M300 220 V254 Q300 270 316 270 H438 Q455 270 455 286 V322"/><path '+edge('retrieve','used')+' d="M145 416 V459 Q145 477 163 477 H281 Q300 477 300 497 V525"/><path '+edge('tool','used')+' d="M455 416 V459 Q455 477 437 477 H319 Q300 477 300 497 V525"/><path class="edge '+(r?'used':'')+'" d="M300 619 V650"/><text x="132" y="306">정책 · 반품</text><text x="421" y="306">주문 · 환불</text></svg><div class="terminal start">입력</div>'+definitions.map(n=>{const c=cfg[n.id],summary=n.fields.includes('model')?c.model:n.fields.includes('knowledge')?c.knowledge:c.tools.join(', ')||'도구 없음',status=statuses[n.id];return '<button class="node node-'+n.id+' '+(state.selected===n.id?'active':'')+' '+(status==='생략'?'skipped':'')+'" data-action="node" data-node="'+n.id+'" aria-pressed="'+(state.selected===n.id)+'"><span class="node-icon" aria-hidden="true">'+n.icon+'</span><span class="node-copy"><strong>'+n.name+'</strong><small>'+safe(summary)+'</small></span><span class="node-state '+(status==='완료'?'done':status==='진행'?'running':'')+'" title="'+safe(status||'대기')+'" aria-label="'+safe(status||'대기')+'">'+(status==='완료'?'✓':status==='진행'?'◌':status==='생략'?'−':'')+'</span>'+(dirty(n.id)&&!viewed()&&state.mode!=='trace'?'<span class="edited" title="설정 변경" aria-label="설정 변경"></span>':'')+'</button>'}).join('')+'<div class="terminal finish">출력</div></div><div class="canvas-footer"><span class="canvas-caption">'+(r?route==='tool'?'주문 경로':'정책 경로':'')+'</span><span class="canvas-help">노드를 선택해 편집</span></div></div></section>'}

function inspector(){const n=definitions.find(n=>n.id===state.selected),c=(viewed()?.config||state.draft)[n.id],ro=!!viewed(),dis=ro?'disabled':'';
return '<section class="panel inspector"><div class="panel-head"><h2>'+n.name+'</h2>'+(ro?'<span class="readonly">읽기 전용</span>':button('복구','restore-node','small subtle','aria-label="선택 노드 기본값 복구"'))+'</div><div class="panel-body">'+
(n.fields.includes('model')?field('모델','model',select('model',['balanced','fast','reasoning'],c.model,ro)):'')+
(n.fields.includes('prompt')?field('프롬프트','prompt',select('prompt',n.id==='intent'?['intent v3','intent v2']:['support v12','support v11'],c.prompt,ro))+field('본문','body','<textarea id="body" data-field="body" rows="6" '+dis+'>'+safe(c.body)+'</textarea>'):'')+
(n.fields.includes('knowledge')?field('지식','knowledge',select('knowledge',['고객 서비스 가이드','반품 정책 전용','사내 업무 가이드'],c.knowledge,ro)):'')+
(n.id==='retrieve'?field('검색 수','topK','<input id="topK" data-field="topK" type="number" min="1" max="20" value="'+safe(c.topK)+'" '+dis+'>'):'')+
(n.fields.includes('tools')?'<div class="field"><label>도구</label>'+['order-status','ticket-search','refund-status'].map(t=>'<label class="check"><input type="checkbox" data-tool="'+t+'" '+(c.tools.includes(t)?'checked':'')+' '+dis+'> '+t+'</label>').join('')+'</div>':'')+'</div></section>'}

function outputText(r){return r?.output||''}
function traceOutput(r){const c=r.config[state.selected],input=r.mode==='eval'?r.results[state.item]?.input||'':r.input;if(graphStatuses(r)[state.selected]==='생략')return '이 경로는 수행하지 않았습니다.';switch(state.selected){case'intent':return '분류: '+(branch(input)==='tool'?'주문·환불':'정책·반품')+'\n모델 '+c.model+' · '+c.prompt;case'retrieve':return '출처: '+c.knowledge+'\n검색 옵션: Top K '+(c.topK||5)+'\n근거: 단순 변심 3,000원 · 불량/오배송 무료';case'tool':return c.tools.length?'도구: '+c.tools.join(', ')+'\n논리적 호출 1회 · 시도 1회\n조회 결과: 출고 전':'허용 도구 없음 · 도구 호출 생략';default:return r.mode==='eval'?r.results[state.item]?.output||'항목 결과를 기다리고 있습니다.':r.output}}
function traceView(r){if(!r)return '<div class="empty">수행 후 선택 노드의 관측을 확인할 수 있습니다.</div>';const n=definitions.find(n=>n.id===state.selected),c=r.config[n.id];return '<div class="section-title">'+n.name+' · 실제 적용값</div><div class="trace-box">'+safe(JSON.stringify({node:n.id,model:n.fields.includes('model')?c.model:undefined,prompt:n.fields.includes('prompt')?c.prompt:undefined,knowledge:n.fields.includes('knowledge')?c.knowledge:undefined,tools:n.fields.includes('tools')?c.tools:undefined},null,2))+'</div><div class="section"><div class="section-title">입력</div><div class="trace-box">'+safe(r.mode==='eval'?r.results[state.item]?.input:r.input)+'</div></div><div class="section"><div class="section-title">출력 / 근거</div><div class="trace-box">'+safe(traceOutput(r))+'</div><div class="result-meta"><span>상태 <b>'+graphStatuses(r)[n.id]+'</b></span><span>지연 <b>'+({intent:110,retrieve:186,tool:220,answer:1120})[n.id]+'ms (모의)</b></span></div></div><p class="hint">Langfuse 관측 화면을 모킹했습니다. 실제 API는 호출하지 않습니다.</p>'}
function diffView(r){const baseline=state.history.find(x=>x.id===state.baseline);if(!r||!baseline)return '<div class="empty">이력에서 비교 기준을 지정하세요.</div>';return '<div class="note">기준 '+baseline.id+' → 후보 '+r.id+'</div>'+definitions.map(n=>{const a=baseline.config[n.id],b=r.config[n.id];const changes=Object.keys(b).filter(k=>JSON.stringify(a[k])!==JSON.stringify(b[k]));return '<div class="diff-row"><b>'+n.name+'</b><br>'+(changes.length?changes.map(k=>safe(({model:'모델',prompt:'프롬프트',body:'본문',knowledge:'지식',tools:'도구',topK:'Top K'})[k]||k)+': '+safe(Array.isArray(a[k])?a[k].join(','):a[k])+' → '+safe(Array.isArray(b[k])?b[k].join(','):b[k])).join('<br>'):'<span>설정 변화 없음</span>')+'</div>'}).join('')+
(r.mode==='eval'&&baseline.mode==='eval'?'<div class="section-title section">항목 점수 비교</div><table class="items"><thead><tr><th>항목</th><th>기준</th><th>후보</th><th>차이</th></tr></thead><tbody>'+r.results.map(q=>{const a=baseline.results.find(x=>x.id===q.id&&x.input===q.input),valid=a&&a.score!==null&&q.score!==null&&!q.error;return '<tr><td>'+q.id+'</td><td>'+(a?.score==null?'—':a.score.toFixed(2))+'</td><td>'+(q.score==null?'—':q.score.toFixed(2))+'</td><td>'+(valid?(q.score-a.score>0?'+':'')+(q.score-a.score).toFixed(2):'비교 불가')+'</td></tr>'}).join('')+'</tbody></table>':'')}
function resultsPanel(){const r=result(),ro=!!viewed();return '<section class="panel results"><div class="panel-head"><h2>'+ (state.mode==='run'?'실행':'평가')+'</h2>'+(r?'<span class="result-status '+(r.state==='완료'?'success':'')+'">'+(!ro&&r.state==='완료'&&JSON.stringify(state.draft)!==JSON.stringify(r.config)?'이전 결과':(r.state==='완료'?'✓ ':'')+r.state)+'</span>':'')+'</div><div class="panel-body">'+
(state.mode==='run'?field('입력','input','<textarea id="input" rows="3" '+(ro?'disabled':'')+'>'+safe(ro?r.input:state.input)+'</textarea>'):'<div class="grid2">'+field('데이터셋','dataset','<select id="dataset" '+(ro?'disabled':'')+'>'+opt('고객 지원 회귀 v4','고객 지원 회귀 v4',state.dataset)+'</select>')+field('평가기','judge','<select id="judge" '+(ro?'disabled':'')+'>'+opt('답변 품질 v2','답변 품질 v2',state.judge)+'</select>')+'</div>')+
(state.error?'<p class="form-error" role="alert">'+safe(state.error)+'</p>':'')+
(r?.state==='진행 중'?'<div class="progress"><span style="width:'+r.progress+'%"></span></div>':'')+
'<div class="tabs">'+[['response',state.mode==='run'?'결과':'항목'],['trace','관측'],['compare','비교']].map(([id,name])=>'<button class="'+(state.tab===id?'active':'')+'" data-action="tab" data-tab="'+id+'">'+name+'</button>').join('')+'</div>'+
(state.tab==='trace'?traceView(r):state.tab==='compare'?diffView(r):state.mode==='run'?(r?'<div class="output">'+safe(r.output||'처리 중…')+'</div>':'<div class="empty"><div class="empty-symbol">↗</div>입력을 작성하고 실행하세요.</div>'):evalResults(r))+'</div></section>'}

function evalResults(r){if(!r||r.mode!=='eval')return '<div class="empty">데이터와 평가 기준을 선택한 뒤 평가를 수행하세요.</div>';const valid=r.results.filter(x=>x.score!==null&&!x.error);return '<div class="stats"><div><span>유효 평균</span><strong>'+ (valid.length?(valid.reduce((s,x)=>s+x.score,0)/valid.length).toFixed(2):'—')+'</strong></div><div><span>유효 평가</span><strong>'+valid.length+' / 3</strong></div><div><span>평가 오류</span><strong>'+r.results.filter(x=>x.error).length+'</strong></div></div><table class="items"><thead><tr><th>입력</th><th>점수</th><th>평가</th></tr></thead><tbody>'+r.results.map((q,i)=>'<tr class="'+(state.item===i?'selected':'')+'"><td><button data-action="item" data-item="'+i+'">'+safe(q.input)+'</button></td><td>'+(q.score===null?'—':q.score.toFixed(2))+'</td><td>'+badge(q.error?'평가 오류':q.score===null?'대기':'완료',q.error?'amber':'green')+'</td></tr>').join('')+'</tbody></table><div class="section"><div class="section-title">선택 항목 · '+r.results[state.item]?.id+'</div><div class="output">'+safe(r.results[state.item]?.output||'결과 대기')+'</div><p class="hint">'+safe(r.results[state.item]?.error||(r.results[state.item]?.score===null?'평가 결과 대기':'질문과 정책 조건의 일치 여부를 확인했습니다.'))+'</p>'+button('관측 보기','inspect-item','small')+'</div>'}
function telemetry(r){let offset=0;return definitions.map(n=>{const status=graphStatuses(r)[n.id]||'대기',duration=status==='생략'?0:({intent:110,retrieve:186,tool:220,answer:1120})[n.id],entry={...n,status,start:offset,duration};if(status!=='생략')offset+=duration;return entry})}
function effectiveInput(r){return r.mode==='eval'?r.results[state.item]?.input||'':r.input}
function observationData(r){const judge=state.traceLayer==='judge'&&r.mode==='eval',root=state.obsRoot===true,n=definitions.find(n=>n.id===state.selected),c=r.config[n.id],rows=telemetry(r),entry=rows.find(x=>x.id===n.id),total=rows.reduce((v,x)=>v+x.duration,0),err=judge?r.results[state.item]?.error:null;
return {name:root?(judge?'quality.evaluate':'customer-support'):judge?'quality.judge':n.name,type:root?'TRACE':judge||n.fields.includes('model')?'GENERATION':'SPAN',model:root?'—':judge?'judge-balanced':n.fields.includes('model')?c.model:'—',prompt:root?'—':judge?'quality v2':n.fields.includes('prompt')?c.prompt:'—',duration:judge?520:root?total:entry.duration,tokens:root?'610':judge?'314':n.fields.includes('model')?n.id==='intent'?'60':'550':'—',cost:root?'₩2.3':judge?'₩1.2':n.fields.includes('model')?'₩1.1':'—',status:err?'ERROR':root?r.state:entry.status,input:judge?{input:effectiveInput(r),output:r.results[state.item]?.output,rubric:r.judge}:{input:effectiveInput(r)},output:root?(r.mode==='eval'?r.results[state.item]?.output:r.output):judge?err?{error:err}:{score:r.results[state.item]?.score,reason:'질문과 정책 조건의 일치 여부 확인'}:{output:traceOutput(r)},score:r.mode==='eval'?r.results[state.item]?.score:null,error:err,node:root||judge?null:n.id,config:c}}
function lfWorkspace(){const r=result();if(r&&state.traceLayer!=='judge'&&graphStatuses(r)[state.selected]==='생략')state.selected='answer';if(!r)return '<section class="panel"><div class="empty">실행을 선택하세요.</div></section>';
const judge=state.traceLayer==='judge'&&r.mode==='eval',rows=judge?[{id:'judge',name:'quality.judge',type:'GENERATION',duration:520,start:0,status:r.results[state.item]?.error?'ERROR':'완료'}]:telemetry(r).filter(n=>n.status!=='생략').map(n=>({...n,type:n.fields.includes('model')?'GENERATION':'SPAN'})),total=rows.reduce((v,n)=>v+n.duration,0),obs=observationData(r),timeline=state.traceView==='timeline',query=(state.traceSearch||'').toLowerCase(),shown=rows.filter(n=>(n.name+' '+n.id+' '+n.type).toLowerCase().includes(query));
const treeItem=(n)=>'<button class="lf-tree-row child '+(!state.obsRoot&&(judge||state.selected===n.id)?'selected':'')+' '+(n.status==='생략'?'skipped':'')+'" data-action="lf-node" data-node="'+n.id+'"><span class="lf-type '+(n.type==='LLM'||n.type==='GENERATION'?'generation':'span')+'">'+(n.type==='LLM'||n.type==='GENERATION'?'G':'S')+'</span><span>'+safe(n.name)+'</span><small>'+ (n.status==='생략'?'생략':n.duration+'ms')+'</small></button>';
const tree=timeline?'<div class="lf-ruler"><span>0ms</span><span>'+Math.round(total/2)+'ms</span><span>'+total+'ms</span></div>'+shown.map(n=>'<button class="lf-waterfall '+(!state.obsRoot&&(judge||state.selected===n.id)?'selected':'')+'" data-action="lf-node" data-node="'+n.id+'"><span>'+safe(n.name)+'</span><div class="lf-track"><i style="left:'+n.start/total*100+'%;width:'+n.duration/total*100+'%"></i></div><small>'+n.duration+'ms</small></button>').join(''):'<button class="lf-tree-row root '+(state.obsRoot?'selected':'')+'" data-action="lf-root"><span class="lf-caret" data-action="lf-collapse">'+(state.treeCollapsed?'▸':'▾')+'</span><span class="lf-type trace">T</span><span>'+(judge?'quality.evaluate':'customer-support')+'</span><small>'+total+'ms</small></button>'+(!state.treeCollapsed?shown.map(treeItem).join(''):'');
const tab=state.obsTab||'io';
let detail=tab==='metadata'?'<pre class="lf-json">'+safe(JSON.stringify({run_id:r.mode==='eval'?r.id+'-'+r.results[state.item]?.id:r.id,trace_id:(judge?'judge-trace-':'trace-')+(r.mode==='eval'?r.id+'-'+r.results[state.item]?.id:r.id),observation_id:(r.mode==='eval'?r.id+'-'+r.results[state.item]?.id:r.id)+'-'+(judge?'judge':state.obsRoot?'root':state.selected),node_id:obs.node,agent_version:'build-17',snapshot_id:'snapshot-'+r.id,prompt:obs.prompt,model:obs.model},null,2))+'</pre>':tab==='scores'?(r.mode==='eval'?'<div class="lf-score"><span>'+safe(r.judge)+'</span><strong>'+ (obs.error?'평가 오류':obs.score===null?'—':obs.score?.toFixed(2))+'</strong></div><p class="lf-note">'+(obs.error?safe(obs.error):'질문과 정책 조건의 일치 여부를 확인했습니다.')+'</p>':'<div class="empty">이 실행에 연결된 점수가 없습니다.</div>'):'<div class="lf-io"><section><div class="lf-io-head">Input <span>JSON</span></div><pre>'+safe(JSON.stringify(obs.input,null,2))+'</pre></section><section><div class="lf-io-head">Output <span>JSON</span></div><pre>'+safe(JSON.stringify(obs.output,null,2))+'</pre></section></div>';
return '<section class="lf-card"><div class="lf-context"><div class="lf-selector">'+field('Trace','trace-run','<select id="trace-run">'+state.history.map(h=>opt(h.id,h.id+' · '+(h.mode==='eval'?'평가':'실행'),r.id)).join('')+'</select>')+(r.mode==='eval'?field('항목','trace-item','<select id="trace-item">'+r.results.map((q,i)=>opt(String(i),q.id+' · '+q.input,String(state.item))).join('')+'</select>'):'')+'</div><div class="lf-context-actions"><button data-action="trace-layer" data-layer="business" class="'+(!judge?'on':'')+'">업무</button>'+(r.mode==='eval'?'<button data-action="trace-layer" data-layer="judge" class="'+(judge?'on':'')+'">평가기</button>':'')+'</div></div><div class="lf-head"><span>Trace / <strong>'+ (judge?'quality.evaluate':'customer-support')+'</strong></span><div><span>'+total+'ms</span><span>'+ (judge?'314':'610')+' tokens</span><span>'+ (judge?'₩1.2':'₩2.3')+'</span></div></div><div class="lf-body"><aside class="lf-tree"><div class="lf-tree-controls"><button data-action="lf-view" data-view="tree" class="'+(!timeline?'on':'')+'">Tree</button><button data-action="lf-view" data-view="timeline" class="'+(timeline?'on':'')+'">Timeline</button></div><input id="trace-search" aria-label="관측 검색" placeholder="관측 검색" value="'+safe(state.traceSearch||'')+'"><div class="lf-tree-list">'+tree+(shown.length?'':'<div class="empty">일치하는 관측이 없습니다.</div>')+'</div></aside><section class="lf-detail"><div class="lf-observation-head"><div><span class="lf-type '+(obs.type==='GENERATION'?'generation':obs.type==='TRACE'?'trace':'span')+'">'+obs.type[0]+'</span><strong>'+safe(obs.name)+'</strong></div><span class="lf-level '+(obs.status==='ERROR'?'error':'')+'">'+safe(obs.status)+'</span></div><div class="lf-properties">'+[['모델',obs.model],['시간',obs.duration+'ms'],['토큰',obs.tokens],['비용',obs.cost]].map(x=>'<div><small>'+x[0]+'</small><span>'+safe(x[1])+'</span></div>').join('')+'</div><div class="lf-tabs">'+[['io','입출력'],['metadata','메타데이터'],['scores','점수']].map(([id,title])=>'<button data-action="lf-tab" data-tab="'+id+'" class="'+(tab===id?'on':'')+'">'+title+'</button>').join('')+'</div>'+detail+'</section></div></section>'}
function historyPanel(){let rows=state.history;if(state.filter==='current'&&state.mode!=='trace')rows=rows.filter(r=>r.mode===state.mode);return '<aside class="panel history" aria-label="수행 이력 사이드바"><div class="panel-head"><h2>이력</h2>'+button('×','history','small subtle','aria-label="이력 닫기"')+'</div><div class="panel-body"><select class="history-filter" id="history-filter" aria-label="이력 필터">'+opt('current','현재 모드',state.filter)+opt('all','전체',state.filter)+'</select>'+rows.map(r=>'<button class="history-card '+(r.id===state.viewId?'active':'')+'" data-action="view-history" data-id="'+r.id+'"><div class="history-top"><span>'+r.time+'</span><span>'+r.state+'</span></div><strong>'+safe(r.input)+'</strong><small>'+r.id+(state.baseline===r.id?' · 기준':'')+'</small></button>').join('')+(viewed()?'<div class="history-footer">'+button('가져오기','import-history','small')+button('기준 지정','set-baseline','small')+'</div>':'')+'</div></aside>'}

function render(){const focused=document.activeElement,focusId=focused?.id,start=focused?.selectionStart,end=focused?.selectionEnd;save();const r=viewed();$('#app').innerHTML='<div class="titlebar"><div class="agent-title"><span class="agent-logo" aria-hidden="true">◈</span><h1>고객 지원</h1><span class="demo-label">데모</span></div><div class="actions"><div class="segmented" aria-label="수행 모드"><button data-action="mode" data-mode="run" class="'+(state.mode==='run'?'active':'')+'">실행</button><button data-action="mode" data-mode="eval" class="'+(state.mode==='eval'?'active':'')+'">평가</button><button data-action="mode" data-mode="trace" class="'+(state.mode==='trace'?'active':'')+'">추적</button></div>'+button('이력','history',state.historyOpen?'active':'')+(state.mode==='trace'?'':button(r?'편집으로':running?'실행 중…':state.mode==='run'?'↗ 실행':'↗ 평가',r?'return-draft':'perform','primary',running&&!r?'disabled':''))+(running?button('중단','cancel'):'')+'</div></div>'+
(r?'<div class="history-banner">이전 '+(r.mode==='eval'?'평가':'실행')+' · '+r.time+'<button data-action="return-draft">편집으로 돌아가기 ↗</button></div>':'')+
'<div class="workspace '+(state.mode==='trace'?'trace-workspace ':'')+(state.historyOpen?'with-history':'')+'">'+(state.mode==='trace'?lfWorkspace():graph()+inspector()+resultsPanel())+(state.historyOpen?historyPanel():'')+'</div>';if(focusId&&document.getElementById(focusId)){const el=document.getElementById(focusId);el.focus({preventScroll:true});if(typeof start==='number'&&el.setSelectionRange)el.setSelectionRange(start,end)}}

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function perform(){state.error='';if(!state.input.trim()&&state.mode==='run'){state.error='고객 입력을 작성하세요.';render();return}
for(const n of definitions){const c=state.draft[n.id];if(n.fields.includes('prompt')&&!c.body.trim()){state.selected=n.id;state.error=n.name+'의 프롬프트 본문을 작성하세요.';render();return}if(n.id==='retrieve'&&(!Number.isInteger(Number(c.topK))||Number(c.topK)<1||Number(c.topK)>20)){state.selected=n.id;state.error='검색 Top K는 1–20 정수로 입력하세요.';render();return}}
const r={id:(state.mode==='eval'?'EXP-':'RUN-')+Date.now().toString().slice(-5),mode:state.mode,input:state.mode==='run'?state.input:state.dataset,time:'방금',config:copy(state.draft),statuses:Object.fromEntries(definitions.map(n=>[n.id,'대기'])),state:'진행 중',progress:0,output:'',results:state.mode==='eval'?samples.map(q=>({...q,score:null,error:null,output:''})):[],judge:state.judge,dataset:state.dataset,changed:definitions.filter(n=>dirty(n.id)).map(n=>n.id)};state.history.unshift(r);state.resultId=r.id;state.viewId=null;state.item=0;state.tab='response';r.route=r.mode==='run'?branch(r.input):null;running=r;const token=++runToken,sequence=r.mode==='run'?['intent',r.route,'answer']:['intent','retrieve','tool','answer'];let i=0;
if(r.mode==='run')r.statuses[r.route==='tool'?'retrieve':'tool']='생략';
function step(){if(token!==runToken)return;if(i>0)r.statuses[sequence[i-1]]='완료';if(i<sequence.length){r.statuses[sequence[i]]='진행';r.progress=i/sequence.length*100;i++;render();setTimeout(step,450)}else{r.state='완료';r.progress=100;r.output=/배송지|출고/.test(r.input)?'출고 전에는 주문 내역에서 배송지를 변경할 수 있습니다. 출고 후에는 고객센터에 문의해주세요.':r.input.includes('환불')?'환불은 영업일 기준 3~5일이 필요합니다.':'단순 변심 반품의 배송비는 3,000원입니다. 상품 불량이나 오배송은 무료입니다.\n\n주문 내역에서 반품을 접수할 수 있습니다.';
if(r.mode==='eval')r.results=samples.map((q,j)=>({...q,score:j===2?null:r.config.answer.model==='reasoning'?[.97,.94][j]:[.93,.83][j],error:j===2?'Judge 일시 오류':null,output:q.expected}));
running=null;render();toast('완료');}}step()}

document.addEventListener('input',e=>{const x=e.target;if(x.dataset.field&&!viewed()){state.draft[state.selected][x.dataset.field]=x.value;save()}if(x.id==='input'){state.input=x.value;save()}if(x.id==='trace-search'){state.traceSearch=x.value;render()}});
document.addEventListener('change',e=>{const x=e.target;if(x.dataset.field&&!viewed()){state.draft[state.selected][x.dataset.field]=x.value;if(x.id==='prompt')state.draft[state.selected].body=x.value.includes('v11')?'질문에 간결하게 답변하세요.':copy(base[state.selected].body);render()}
if(x.dataset.tool&&!viewed()){const ts=new Set(state.draft[state.selected].tools);x.checked?ts.add(x.dataset.tool):ts.delete(x.dataset.tool);state.draft[state.selected].tools=[...ts];render()}
if(x.id==='trace-run'){state.resultId=x.value;state.viewId=null;state.item=0;state.traceLayer='business';render()}if(x.id==='trace-item'){state.item=Number(x.value);render()}if(x.id==='history-filter'){state.filter=x.value;render()}if(x.id==='dataset'){state.dataset=x.value;save()}if(x.id==='judge'){state.judge=x.value;save()}});
document.addEventListener('click',e=>{const x=e.target.closest('[data-action]');if(!x)return;switch(x.dataset.action){
case'node':state.selected=x.dataset.node;if(state.mode==='trace')state.traceLayer='business';render();break;
case'mode':if(viewed())state.viewId=null;beforeHistory=null;state.mode=x.dataset.mode;state.resultId=state.mode==='trace'?(state.resultId||state.history[0]?.id||null):(state.history.find(r=>r.mode===state.mode)?.id||null);state.item=0;state.tab='response';state.traceLayer='business';render();break;
case'history':state.historyOpen=!state.historyOpen;render();break;
case'restore-node':state.draft[state.selected]=copy(base[state.selected]);render();toast('선택 노드만 기본값으로 복구했습니다.');break;
case'perform':perform();break;
case'cancel':runToken++;if(running){running.state='중단';Object.keys(running.statuses).forEach(k=>{if(running.statuses[k]==='진행')running.statuses[k]='중단'});running=null}render();toast('모의 수행을 중단했습니다. 완료 구간은 유지됩니다.');break;
case'tab':if(x.dataset.tab==='trace'){state.mode='trace';state.traceLayer='business'}else state.tab=x.dataset.tab;render();break;
case'view-history':if(!state.viewId)beforeHistory={mode:state.mode,selected:state.selected,resultId:state.resultId,item:state.item,tab:state.tab};state.viewId=x.dataset.id;if(state.mode!=='trace')state.mode=viewed().mode;state.item=0;state.tab='response';render();break;
case'return-draft':state.viewId=null;if(beforeHistory){Object.assign(state,beforeHistory);beforeHistory=null}else state.item=0;render();toast('현재 초안을 복원했습니다.');break;
case'import-history':state.draft=copy(viewed().config);state.viewId=null;beforeHistory=null;render();toast('이력 설정을 새 초안으로 가져왔습니다.');break;
case'set-baseline':state.baseline=state.viewId;toast('비교 기준을 '+state.baseline+'로 지정했습니다.');render();break;
case'item':state.item=Number(x.dataset.item);render();break;
case'inspect-item':state.mode='trace';state.traceLayer='business';render();break;
case'trace-layer':state.traceLayer=x.dataset.layer;state.obsRoot=false;render();break;
case'lf-node':if(x.dataset.node!=='judge')state.selected=x.dataset.node;state.obsRoot=false;render();break;
case'lf-root':state.obsRoot=true;render();break;
case'lf-collapse':state.treeCollapsed=!state.treeCollapsed;render();break;
case'lf-view':state.traceView=x.dataset.view;render();break;
case'lf-tab':state.obsTab=x.dataset.tab;render();break;
case'reset':runToken++;running=null;beforeHistory=null;state={...state,mode:'run',selected:'answer',draft:copy(base),input:samples[0].input,history:preset(),historyOpen:false,viewId:null,baseline:'EXP-041',resultId:null,item:0,tab:'response',error:''};render();toast('모의 데이터와 초안을 초기화했습니다.');break;
}});
render();
